import { z } from 'zod'
import { subDays, startOfDay, endOfDay, differenceInCalendarDays } from 'date-fns'

export const RangeSchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

export type AnalyticsRange = { from: string; to: string }
export type ParsedRange = {
  current: AnalyticsRange
  prior?: AnalyticsRange
  compare: boolean
}

/** Default date range: last 30 days (today included). */
export function defaultLast30(): AnalyticsRange {
  const today = new Date()
  return {
    from: startOfDay(subDays(today, 29)).toISOString(),
    to: endOfDay(today).toISOString(),
  }
}

/**
 * Parse from/to/compare out of URL search params (or a plain object).
 * Falls back to last-30d when from/to are absent or invalid.
 */
export function parseRange(
  searchParams: URLSearchParams | Record<string, string | undefined>,
): ParsedRange {
  const raw =
    searchParams instanceof URLSearchParams
      ? Object.fromEntries(searchParams.entries())
      : searchParams

  const result = RangeSchema.safeParse(raw)
  const data = result.success ? result.data : { from: undefined, to: undefined, compare: '0' as const }

  const fallback = defaultLast30()
  const current: AnalyticsRange = {
    from: data.from ?? fallback.from,
    to: data.to ?? fallback.to,
  }
  const compare = data.compare === '1'

  return {
    current,
    prior: compare ? priorRange(current) : undefined,
    compare,
  }
}

/**
 * Given a range, return the equal-length window immediately before it.
 * E.g. Apr 1–30 → Mar 1–31 (30d prior).
 */
export function priorRange(r: AnalyticsRange): AnalyticsRange {
  const days = rangeDays(r)
  const fromDate = new Date(r.from)
  const toDate = new Date(r.to)
  return {
    from: startOfDay(subDays(fromDate, days)).toISOString(),
    to: endOfDay(subDays(toDate, days)).toISOString(),
  }
}

/** Number of calendar days the range spans (inclusive). */
export function rangeDays(r: AnalyticsRange): number {
  const diff = differenceInCalendarDays(new Date(r.to), new Date(r.from))
  return Math.max(diff, 1)
}

/**
 * Suggest a SQL group_by granularity based on range size.
 * ≤30d → day, 31–180d → week, >180d → month
 */
export function pickGroupBy(days: number): 'day' | 'week' | 'month' {
  if (days <= 30) return 'day'
  if (days <= 180) return 'week'
  return 'month'
}

import Papa from 'papaparse'

export interface CsvExportOptions<T extends Record<string, unknown>> {
  /** Filename without extension — extension `.csv` appended automatically. */
  filename: string
  rows: T[]
  /** Optional column header overrides. Key = row key, value = display header. */
  headers?: Partial<Record<keyof T, string>>
}

/**
 * Export rows as a CSV file. Browser-only — triggers a Blob download.
 * Uses papaparse for RFC-4180 compliant serialization.
 */
export function exportRows<T extends Record<string, unknown>>(
  opts: CsvExportOptions<T>,
): void {
  const { filename, rows, headers } = opts

  if (rows.length === 0) return

  // Build column list from first row
  const keys = Object.keys(rows[0]!) as Array<keyof T>

  // Apply header overrides
  const fields = keys.map((k) =>
    headers && headers[k] ? String(headers[k]) : String(k),
  )

  // Re-map rows to use display headers as keys
  const remapped = rows.map((row) => {
    const out: Record<string, unknown> = {}
    keys.forEach((k, i) => {
      out[fields[i]!] = row[k]
    })
    return out
  })

  const csv = Papa.unparse(remapped, { header: true })
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename.endsWith('.csv') ? filename : `${filename}.csv`
  anchor.style.display = 'none'
  document.body.appendChild(anchor)
  anchor.click()
  document.body.removeChild(anchor)
  URL.revokeObjectURL(url)
}

