'use client'

import { useEffect } from 'react'
import { usePathname } from 'next/navigation'
import { useAnalyticsExport } from '@/components/reports/AnalyticsExportProvider'
import { exportRows } from '@/lib/csv-export'

interface UseExportCsvOptions<T extends Record<string, unknown>> {
  /** Filename stem — no extension, no path. Date range appended by toolbar. */
  filename: string
  /** Called on export. Must return rows synchronously or a Promise. */
  getRows: () => T[] | Promise<T[]>
  /** Optional column header display overrides. */
  headers?: Partial<Record<keyof T, string>>
}

/**
 * Register a CSV serializer for the current page with the global AnalyticsToolbar.
 * Auto-registers on mount, deregisters on unmount.
 * Call once per tab client component.
 */
export function useExportCsv<T extends Record<string, unknown>>(
  opts: UseExportCsvOptions<T>,
): void {
  const pathname = usePathname()
  const { register, unregister } = useAnalyticsExport()

  useEffect(() => {
    const serializer = async (rangeLabel: string) => {
      const rows = await opts.getRows()
      if (rows.length === 0) return
      exportRows({
        filename: `${opts.filename}-${rangeLabel}`,
        rows,
        headers: opts.headers as Partial<Record<string, unknown>>,
      })
    }

    register(pathname, serializer)
    return () => unregister(pathname)
    // We intentionally exclude opts from the dep array — callers should
    // memoize getRows if they care about identity. Stale-closure is safe
    // because the serializer is invoked lazily on click, not on re-render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathname, register, unregister])
}

'use client'

import {
  createContext,
  useCallback,
  useContext,
  useRef,
} from 'react'
import type { ReactNode } from 'react'

type Serializer = (rangeLabel: string) => void | Promise<void>

interface ExportContextValue {
  register: (pathname: string, fn: Serializer) => void
  unregister: (pathname: string) => void
  invoke: (pathname: string, rangeLabel: string) => Promise<void>
}

const ExportContext = createContext<ExportContextValue | null>(null)

/**
 * Registry of per-tab CSV serializers.
 * Each tab calls useExportCsv() which registers itself here via pathname key.
 * The AnalyticsToolbar reads the current pathname and calls invoke().
 */
export function AnalyticsExportProvider({ children }: { children: ReactNode }) {
  // useRef so mutations don't trigger re-renders
  const registry = useRef<Map<string, Serializer>>(new Map())

  const register = useCallback((pathname: string, fn: Serializer) => {
    registry.current.set(pathname, fn)
  }, [])

  const unregister = useCallback((pathname: string) => {
    registry.current.delete(pathname)
  }, [])

  const invoke = useCallback(async (pathname: string, rangeLabel: string) => {
    const fn = registry.current.get(pathname)
    if (fn) await fn(rangeLabel)
  }, [])

  return (
    <ExportContext.Provider value={{ register, unregister, invoke }}>
      {children}
    </ExportContext.Provider>
  )
}

export function useAnalyticsExport(): ExportContextValue {
  const ctx = useContext(ExportContext)
  if (!ctx) {
    throw new Error('useAnalyticsExport must be used inside AnalyticsExportProvider')
  }
  return ctx
}

'use client'

import { useCallback, useState } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { subDays, startOfDay, endOfDay, format } from 'date-fns'
import { Download } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { DateRangePicker } from '@/components/ui/date-range-picker'
import type { DateRange } from '@/components/ui/date-range-picker'
import { useAnalyticsExport } from '@/components/reports/AnalyticsExportProvider'
import { cn } from '@/lib/utils'

function buildDefaultRange(): DateRange {
  const today = new Date()
  return {
    from: startOfDay(subDays(today, 29)),
    to: endOfDay(today),
  }
}

function toParam(d: Date): string {
  return format(d, 'yyyy-MM-dd')
}

function rangeLabel(range: DateRange): string {
  const from = range.from ? format(range.from, 'yyyy-MM-dd') : 'na'
  const to = range.to ? format(range.to, 'yyyy-MM-dd') : 'na'
  return `${from}_${to}`
}

/**
 * Global analytics toolbar — mounts in the reports layout above page content.
 * Controls:
 *   DateRangePicker → writes ?from=YYYY-MM-DD&to=YYYY-MM-DD
 *   Compare toggle  → writes ?compare=1 / removes when off
 *   Export CSV      → calls registered tab serializer via AnalyticsExportProvider
 */
export function AnalyticsToolbar({ className }: { className?: string }) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const { invoke } = useAnalyticsExport()
  const [exporting, setExporting] = useState(false)

  // Derive current range from URL params, fall back to last-30d
  const fromParam = searchParams.get('from')
  const toParam_ = searchParams.get('to')
  const compareParam = searchParams.get('compare') === '1'

  const defaultRange = buildDefaultRange()
  const currentRange: DateRange = {
    from: fromParam ? new Date(fromParam) : defaultRange.from,
    to: toParam_ ? new Date(toParam_) : defaultRange.to,
  }

  function handleRangeChange(range: DateRange) {
    if (!range.from || !range.to) return
    const params = new URLSearchParams(searchParams.toString())
    params.set('from', toParam(range.from))
    params.set('to', toParam(range.to))
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  function handleCompareToggle(checked: boolean) {
    const params = new URLSearchParams(searchParams.toString())
    if (checked) {
      params.set('compare', '1')
    } else {
      params.delete('compare')
    }
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const handleExport = useCallback(async () => {
    setExporting(true)
    try {
      await invoke(pathname, rangeLabel(currentRange))
    } finally {
      setExporting(false)
    }
  }, [invoke, pathname, currentRange])

  return (
    <div
      className={cn(
        // Sticky on scroll, bone background, hairline bottom border
        'sticky top-0 z-20 bg-[var(--color-bone)] border-b border-[var(--color-border)]',
        'py-3 px-0',
        className,
      )}
    >
      {/* Inner row — responsive stack */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-end">
        {/* Compare toggle */}
        <div className="flex items-center gap-2">
          <Switch
            id="analytics-compare"
            checked={compareParam}
            onCheckedChange={handleCompareToggle}
          />
          <Label
            htmlFor="analytics-compare"
            className="text-sm text-[var(--color-stone)] cursor-pointer select-none"
          >
            Compare to prior period
          </Label>
        </div>

        {/* Date range picker */}
        <DateRangePicker
          value={currentRange}
          onValueChange={handleRangeChange}
          className="w-full sm:w-auto font-[tabular-nums]"
        />

        {/* Export CSV */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleExport}
          disabled={exporting}
          className="shrink-0 border-[var(--color-border)] text-[var(--color-onyx)] hover:bg-[var(--color-onyx)] hover:text-[var(--color-bone)] transition-colors"
        >
          <Download className="mr-2 size-3.5" aria-hidden="true" />
          {exporting ? 'Exporting…' : 'Export CSV'}
        </Button>
      </div>
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
  group_by: z.enum(['day', 'week', 'month']).default('day'),
})

interface TimelineItem {
  period: string
  revenue: number
  deposits: number
  tips: number
  count: number
}

interface RevenueKpis {
  totalRevenue: number
  avgSessionValue: number
  depositsCollected: number
  tipsCollected: number
  sessionsCompleted: number
}

interface RevenueBlock {
  timeline: TimelineItem[]
  kpis: RevenueKpis
}

async function fetchRevenue(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string,
  to: string,
  groupBy: 'day' | 'week' | 'month',
): Promise<RevenueBlock> {
  const { data: bookings, error } = await supabase
    .from('bookings')
    .select('id, scheduled_at, price_cents, deposit_cents, tip_cents, artist_id, service_id, location_id, status')
    .eq('studio_id', studioId)
    .eq('status', 'completed')
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)
    .order('scheduled_at', { ascending: true })

  if (error) throw error

  const grouped = (bookings ?? []).reduce<Record<string, TimelineItem>>((acc, b) => {
    const d = new Date(b.scheduled_at)
    let key: string
    if (groupBy === 'month') key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    else if (groupBy === 'week') {
      const startOfYear = new Date(d.getFullYear(), 0, 1)
      const week = Math.ceil(((d.getTime() - startOfYear.getTime()) / 86400000 + startOfYear.getDay() + 1) / 7)
      key = `${d.getFullYear()}-W${String(week).padStart(2, '0')}`
    } else key = d.toISOString().slice(0, 10)

    const rev = b.price_cents ?? 0
    const tips = b.tip_cents ?? 0
    const dep = b.deposit_cents ?? 0
    if (!acc[key]) acc[key] = { period: key, revenue: 0, deposits: 0, tips: 0, count: 0 }
    const entry = acc[key]!
    entry.revenue += rev
    entry.deposits += dep
    entry.tips += tips
    entry.count++
    return acc
  }, {})

  const timeline = Object.values(grouped).sort((a, b) => a.period.localeCompare(b.period))
  const totalRevenue = timeline.reduce((s, r) => s + r.revenue, 0)
  const totalDeposits = timeline.reduce((s, r) => s + r.deposits, 0)
  const totalTips = timeline.reduce((s, r) => s + r.tips, 0)
  const count = bookings?.length ?? 0
  const avgSessionValue = count > 0 ? Math.round(totalRevenue / count) : 0

  return {
    timeline,
    kpis: {
      totalRevenue,
      avgSessionValue,
      depositsCollected: totalDeposits,
      tipsCollected: totalTips,
      sessionsCompleted: count,
    },
  }
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { group_by, compare } = parsed.data
  const supabase = await createClient()

  const { current } = parseRange(req.nextUrl.searchParams)

  try {
    if (compare === '1') {
      const prior = priorRange(current)
      const [currentBlock, priorBlock] = await Promise.all([
        fetchRevenue(supabase, auth.studioId, current.from, current.to, group_by),
        fetchRevenue(supabase, auth.studioId, prior.from, prior.to, group_by),
      ])
      return Response.json({ current: currentBlock, prior: priorBlock })
    }

    const currentBlock = await fetchRevenue(supabase, auth.studioId, current.from, current.to, group_by)
    return Response.json({ current: currentBlock })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'revenue report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface ArtistStat {
  artistId: string
  artistName: string
  revenue: number
  sessions: number
  noShows: number
  tips: number
  avgTipPct: number
  noShowRate: number
}

interface ArtistsBlock {
  leaderboard: ArtistStat[]
}

async function fetchArtists(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string,
  to: string,
): Promise<ArtistsBlock> {
  const { data: bookings, error } = await supabase
    .from('bookings')
    .select('id, artist_id, price_cents, deposit_cents, tip_cents, status, scheduled_at, artists(profiles(full_name))')
    .eq('studio_id', studioId)
    .in('status', ['completed', 'no_show'])
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)

  if (error) throw error

  const artistMap = new Map<string, {
    artistId: string
    artistName: string
    revenue: number
    sessions: number
    noShows: number
    tips: number
  }>()

  for (const b of bookings ?? []) {
    if (!b.artist_id) continue
    const artistData = b.artists as unknown as { profiles: { full_name: string | null } | null } | null
    const name = artistData?.profiles?.full_name

    const existing = artistMap.get(b.artist_id) ?? {
      artistId: b.artist_id,
      artistName: (name as string | null | undefined) ?? 'Unknown',
      revenue: 0,
      sessions: 0,
      noShows: 0,
      tips: 0,
    }

    if (b.status === 'completed') {
      existing.revenue += (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
      existing.sessions++
      existing.tips += b.tip_cents ?? 0
    } else {
      existing.noShows++
    }

    artistMap.set(b.artist_id, existing)
  }

  const leaderboard = Array.from(artistMap.values())
    .map((a) => ({
      ...a,
      avgTipPct: a.revenue > 0 ? Math.round((a.tips / a.revenue) * 100) : 0,
      noShowRate: (a.sessions + a.noShows) > 0
        ? Math.round((a.noShows / (a.sessions + a.noShows)) * 100)
        : 0,
    }))
    .sort((a, b) => b.revenue - a.revenue)

  return { leaderboard }
}

