import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange, rangeDays, pickGroupBy } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().optional(),
  to: z.string().optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
  group_by: z.enum(['day', 'week', 'month']).optional(),
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface TimelineItem {
  period: string
  count: number
}

interface ServiceRankItem {
  name: string
  count: number
}

interface BookingsBlock {
  kpis: BookingKpis
  timeline: TimelineItem[]
  heatmap: number[][]
  serviceRanking: ServiceRankItem[]
}

async function fetchBookings(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string,
  to: string,
  groupBy: 'day' | 'week' | 'month',
): Promise<BookingsBlock> {
  const { data: bookings, error } = await supabase
    .from('bookings')
    .select('id, status, scheduled_at, service_id, source, services(name)')
    .eq('studio_id', studioId)
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)
    .order('scheduled_at', { ascending: true })

  if (error) throw error

  const all = bookings ?? []
  const total = all.length
  const completed = all.filter((b) => b.status === 'completed').length
  const noShows = all.filter((b) => b.status === 'no_show').length
  const cancelled = all.filter((b) => b.status === 'cancelled').length

  // Timeline grouped by period
  const grouped = all.reduce<Record<string, number>>((acc, b) => {
    const d = new Date(b.scheduled_at)
    let key: string
    if (groupBy === 'month') key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    else if (groupBy === 'week') {
      const dow = d.getDay()
      const startOfWeek = new Date(d)
      startOfWeek.setDate(d.getDate() - dow)
      key = startOfWeek.toISOString().slice(0, 10)
    } else key = d.toISOString().slice(0, 10)
    acc[key] = (acc[key] ?? 0) + 1
    return acc
  }, {})

  const timeline = Object.entries(grouped)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([period, count]) => ({ period, count }))

  // Day × hour heatmap
  const heatmap: number[][] = Array.from({ length: 7 }, () => Array.from<number>({ length: 24 }).fill(0))
  for (const b of all) {
    const d = new Date(b.scheduled_at)
    const row = heatmap[d.getDay()]
    if (row) row[d.getHours()] = (row[d.getHours()] ?? 0) + 1
  }

  // Service popularity — null service_id grouped as "Walk-in / Unscheduled"
  const serviceCounts = all.reduce<Record<string, { name: string; count: number }>>((acc, b) => {
    const key = b.service_id ?? '__walkin__'
    const svc = b.services
    const name = b.service_id
      ? (Array.isArray(svc) ? (svc[0]?.name ?? b.service_id) : ((svc as { name?: string } | null)?.name ?? b.service_id))
      : 'Walk-in / Unscheduled'
    if (!acc[key]) acc[key] = { name, count: 0 }
    acc[key]!.count++
    return acc
  }, {})

  const serviceRanking = Object.values(serviceCounts).sort((a, b) => b.count - a.count)

  return {
    kpis: {
      total,
      completed,
      noShows,
      cancelled,
      noShowRate: total > 0 ? Math.round((noShows / total) * 100) : 0,
      cancellationRate: total > 0 ? Math.round((cancelled / total) * 100) : 0,
    },
    timeline,
    heatmap,
    serviceRanking,
  }
}

