  const all = outputs ?? []
  const total = all.length
  const totalCost = all.reduce((s, o) => s + (o.cost_cents ?? 0), 0)
  const totalTokens = all.reduce((s, o) => s + (o.tokens_input ?? 0) + (o.tokens_output ?? 0), 0)
  const ratings = all.filter((o) => o.rating != null).map((o) => o.rating as number)
  const avgRating = ratings.length > 0 ? ratings.reduce((s, r) => s + r, 0) / ratings.length : null

  const modelMap = all.reduce<Record<string, { count: number; cost: number }>>((acc, o) => {
    const model = o.model ?? 'unknown'
    if (!acc[model]) acc[model] = { count: 0, cost: 0 }
    acc[model]!.count++
    acc[model]!.cost += o.cost_cents ?? 0
    return acc
  }, {})

  const monthly = all.reduce<Record<string, { count: number; cost: number }>>((acc, o) => {
    const month = o.created_at.slice(0, 7)
    if (!acc[month]) acc[month] = { count: 0, cost: 0 }
    acc[month]!.count++
    acc[month]!.cost += o.cost_cents ?? 0
    return acc
  }, {})

  return {
    kpis: { total, totalCost, totalTokens, avgRating },
    modelBreakdown: Object.entries(modelMap).map(([model, d]) => ({ model, ...d })),
    monthlyTrend: Object.entries(monthly)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, d]) => ({ month, ...d })),
  }
}

