            <CardContent className="p-0">
              <div className="divide-y divide-border/50">
                {leaderboard.map((artist, index) => (
                  <div key={artist.artistId} className="flex items-center gap-4 px-6 py-4">
                    <span className="w-6 text-center text-sm font-bold text-muted-foreground tabular-nums">
                      {index + 1}
                    </span>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium truncate">{artist.artistName}</p>
                      <p className="text-xs text-muted-foreground">
                        {artist.sessions} sessions · {artist.noShows} no-shows
                      </p>
                    </div>
                    <div className="text-right shrink-0">
                      <p className="text-sm font-semibold tabular-nums">{formatCurrency(artist.revenue)}</p>
                      <p className="text-xs text-muted-foreground">revenue</p>
                    </div>
                    <Badge
                      variant={artist.noShowRate > 10 ? 'destructive' : 'outline'}
                      className="shrink-0"
                    >
                      {artist.noShowRate}% no-show
                    </Badge>
                    <Badge variant="secondary" className="shrink-0">
                      {artist.avgTipPct}% tip
                    </Badge>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { UserCircle } from 'lucide-react'
import { formatCurrency } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'

interface ClientsBlock {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
}

interface ClientsResponse {
  current: ClientsBlock
  prior?: ClientsBlock
}

export function ClientsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<ClientsResponse>({
    queryKey: ['reports', 'clients', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/clients?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    if (!data?.current) return []
    const d = data.current
    return [
      { metric: 'Total Clients', value: d.totalClients },
      { metric: 'New Clients', value: d.newClients },
      { metric: 'Returning Clients', value: d.returningClients },
      { metric: 'Inactive (90d)', value: d.inactiveClients },
      { metric: 'Avg LTV (cents)', value: d.avgLtv },
      { metric: 'Retention Rate %', value: d.retentionRate },
    ]
  }, [data])

  useExportCsv({
    filename: 'analytics-clients',
    getRows,
    headers: { metric: 'Metric', value: 'Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={5} />}
      emptySlot={
        <EmptyState
          icon={UserCircle}
          title="No client data yet"
          description="Client retention metrics will appear after their first visit."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        return (
          <div className="space-y-6">
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              <KpiCard label="Total Clients" value={d.totalClients} subtextLabel="all time" icon={Users} index={0} />
              <KpiCard
                label="Returning"
                value={d.returningClients}
                subtextLabel={`${d.retentionRate}% retention rate`}
                icon={Users}
                trend="up"
                index={1}
              />
              <KpiCard
                label="Inactive 90d"
                value={d.inactiveClients}
                subtextLabel="no bookings in 90 days"
                icon={Users}
                invertTrend
                trend={d.inactiveClients > 0 ? 'up' : 'neutral'}
                index={2}
              />
              <KpiCard label="New Clients" value={d.newClients} subtextLabel="1 booking only" icon={Users} index={3} />
              <KpiCard
                label="Avg LTV"
                value={formatCurrency(d.avgLtv)}
                subtextLabel="lifetime value per client"
                icon={Users}
                trend="up"
                index={4}
              />
              <KpiCard
                label="Retention Rate"
                value={`${d.retentionRate}%`}
                subtextLabel="return after first visit"
                icon={Users}
                trend="up"
                index={5}
              />
            </div>
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { CalendarDays, TrendingDown } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface BookingsBlock {
  kpis: BookingKpis
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][]
  serviceRanking: Array<{ name: string; count: number }>
}

interface BookingsResponse {
  current: BookingsBlock
  prior?: BookingsBlock
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

function HeatmapCell({ value, max }: { value: number; max: number }) {
  const intensity = max > 0 ? value / max : 0
  // Use color-mix with oklch onyx token — brand-correct, no HSL issue
  const pct = Math.max(Math.round(intensity * 80), 4)
  return (
    <div
      role="cell"
      title={`${value} bookings`}
      aria-label={`${value} bookings`}
      className="h-3 w-3 rounded-sm"
      style={{
        backgroundColor: `color-mix(in oklch, var(--color-onyx) ${pct}%, transparent)`,
      }}
    />
  )
}

export function BookingsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<BookingsResponse>({
    queryKey: ['reports', 'bookings', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/bookings?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.timeline ?? []).map((r) => ({
      period: r.period,
      count: r.count,
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-bookings',
    getRows,
    headers: { period: 'Period', count: 'Bookings' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={CalendarDays}
          title="No booking data yet"
          description="Bookings will appear here once your first appointment is completed."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const timelineForChart = d.timeline.map((r) => ({ name: r.period, value: r.count }))
        const maxHeat = Math.max(...d.heatmap.flat(), 1)

        return (
          <div className="space-y-6">
            {/* KPIs */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              <KpiCard label="Total Bookings" value={d.kpis.total} subtextLabel="in period" icon={CalendarDays} index={0} />
              <KpiCard label="Completed" value={d.kpis.completed} subtextLabel="sessions completed" icon={CalendarDays} trend="up" index={1} />
              <KpiCard label="No-Shows" value={d.kpis.noShows} subtextLabel={`${d.kpis.noShowRate}% no-show rate`} icon={TrendingDown} invertTrend trend={d.kpis.noShows > 0 ? 'up' : 'neutral'} index={2} />
              <KpiCard label="Cancelled" value={d.kpis.cancelled} subtextLabel={`${d.kpis.cancellationRate}% cancellation rate`} icon={TrendingDown} invertTrend trend={d.kpis.cancelled > 0 ? 'up' : 'neutral'} index={3} />
              <KpiCard label="No-Show Rate" value={`${d.kpis.noShowRate}%`} subtextLabel="of total bookings" icon={TrendingDown} invertTrend trend={d.kpis.noShowRate > 10 ? 'up' : 'neutral'} index={4} />
              <KpiCard label="Cancellation Rate" value={`${d.kpis.cancellationRate}%`} subtextLabel="of total bookings" icon={TrendingDown} invertTrend trend={d.kpis.cancellationRate > 15 ? 'up' : 'neutral'} index={5} />
            </div>

            {/* Timeline */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Bookings Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState icon={CalendarDays} title="No booking data yet" description="Bookings will appear here once created." />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Bookings"
                    formatValue={(v) => `${v}`}
                  />
                )}
              </CardContent>
            </Card>

            {/* Heatmap — brand-correct colors */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Booking Heatmap — Day × Hour</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="overflow-x-auto">
                  <div
                    role="grid"
                    aria-label="Booking frequency heatmap"
                    className="inline-flex flex-col gap-1 min-w-max"
                  >
                    <div className="flex gap-1 pl-8" role="row">
                      {Array.from({ length: 24 }, (_, h) => (
                        <div
                          key={h}
                          role="columnheader"
                          className="w-3 text-center text-[9px] text-muted-foreground leading-none"
                        >
                          {h % 6 === 0 ? `${h}` : ''}
                        </div>
                      ))}
                    </div>
                    {d.heatmap.map((row, dayIndex) => (
                      <div key={dayIndex} role="row" className="flex items-center gap-1">
                        <span className="w-7 text-right text-[10px] text-muted-foreground shrink-0">
                          {DAYS[dayIndex]}
                        </span>
                        {row.map((val, h) => (
                          <HeatmapCell key={h} value={val} max={maxHeat} />
                        ))}
                      </div>
                    ))}
                  </div>
                </div>
                <p className="mt-3 text-xs text-muted-foreground">Darker = more bookings at that day/hour.</p>
              </CardContent>
            </Card>

            {/* Service ranking */}
            {d.serviceRanking.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Services by Popularity</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.serviceRanking.slice(0, 10).map((svc, i) => (
                      <div key={svc.name} className="flex items-center gap-4 px-6 py-3">
                        <span className="w-5 text-center text-sm font-bold text-muted-foreground tabular-nums">{i + 1}</span>
                        <span className="flex-1 text-sm font-medium truncate">{svc.name}</span>
                        <Badge variant="secondary">{svc.count} bookings</Badge>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}
